UNDO=False
# dasdmod1: take the 1970 "lastModulation" out of dasd's widget budget preferences (heat-20261114, unified log of 2026-11-13).
# /private/var/mobile/Library/Preferences/com.apple.dasd.widgetRefreshBudgets.plist holds lastModulation = 1970-01-01 00:00:34
# (the mirror of 11-13 22:33): -[_DASBudgetModulator _queue_modulateBudgets] found the stored 2026 date in the future of the
# 1970 boot clock, took "now" and stored it; after timed's settimeofday it logs "Last modulated budgets at Thu Jan  1 01:00:34
# 1970, modulating for 1993998 slots" and walks them through coreduetd (one _DKPredictionQuery of 0.45 s per 8 slots and per
# widget budget): coreduetd at 80-90 % of a big core for the whole uptime, and the date is only stored again when the walk ends.
# Kernel patch 0530 (clock floor) stops new 1970 dates; this block removes the one that is already stored, else the first boot of
# the new kernel walks the same 56 years.  Without the key the modulator does one slot and stores the current date (the method's
# own nil path).  Only a date before 2020 is removed.  Receipt /private/var/db/nord2-stock/dasdmod1.json (the file as it was);
# the undo restores exactly that while the key is still absent.  Idempotent; DASDMOD1_REFUSED = no change.
import os, json, hashlib, plistlib, base64, datetime
R='/work/root'; PL='/private/var/mobile/Library/Preferences/com.apple.dasd.widgetRefreshBudgets.plist'; KEY='lastModulation'
D='/private/var/db/nord2-stock'; REC=D+'/dasdmod1.json'; LIMIT=datetime.datetime(2020,1,1)
sha=lambda b: hashlib.sha256(b).hexdigest(); rd=lambda p: open(R+p,'rb').read()
def put(path, data, mode, uid, gid):
    tmp=R+path+'.nord2tmp'
    if os.path.lexists(tmp): os.remove(tmp)
    with open(tmp,'xb') as f: f.write(data); f.flush(); os.fsync(f.fileno())
    os.chmod(tmp,mode); os.chown(tmp,uid,gid); os.replace(tmp,R+path)
    assert rd(path)==data
def drop_rec():
    os.remove(R+REC)
    if os.path.isdir(R+D) and not os.listdir(R+D): os.rmdir(R+D)
rec=json.load(open(R+REC)) if os.path.exists(R+REC) else None
if not os.path.isfile(R+PL): print('DASDMOD1_REFUSED no com.apple.dasd.widgetRefreshBudgets.plist (nothing stored: nothing to do)')
else:
    raw=rd(PL); st=os.stat(R+PL)
    try: cfg=plistlib.loads(raw)
    except Exception as e: cfg=None
    fmt=plistlib.FMT_BINARY if raw[:6]==b'bplist' else plistlib.FMT_XML
    if not isinstance(cfg,dict): print('DASDMOD1_REFUSED the preferences file is not a dictionary')
    elif not UNDO:
        v=cfg.get(KEY)
        if rec is not None and KEY not in cfg: print('DASDMOD1_INSTALL already (lastModulation absent, receipt present)')
        elif rec is not None: print('DASDMOD1_REFUSED receipt present but lastModulation is', repr(v), ': undo first')
        elif KEY not in cfg: print('DASDMOD1_INSTALL lastModulation absent (no receipt): nothing to change')
        elif not isinstance(v,datetime.datetime): print('DASDMOD1_REFUSED lastModulation has an unexpected value', repr(v))
        elif v>=LIMIT: print('DASDMOD1_INSTALL lastModulation is', v.isoformat(), '(not a 1970-clock date): left alone')
        else:
            rec={'by':'heat-20261114 dasdmod1','path':PL,'key':KEY,'old_value':v.isoformat(),'sha_before':sha(raw),'file_before_b64':base64.b64encode(raw).decode()}
            os.makedirs(R+D,exist_ok=True)
            with open(R+REC,'w') as f: json.dump(rec,f,indent=1); f.flush(); os.fsync(f.fileno())
            del cfg[KEY]; out=plistlib.dumps(cfg,fmt=fmt,sort_keys=False)
            put(PL,out,st.st_mode&0o7777,st.st_uid,st.st_gid); assert plistlib.loads(rd(PL))==cfg
            print('DASDMOD1_INSTALL lastModulation %s removed (%d widget budgets and %d other keys untouched)'%(rec['old_value'],len(cfg.get('budgets',{})),len(cfg)-1))
    else:
        if rec is None: print('DASDMOD1_UNDO nothing to undo')
        elif KEY in cfg:
            drop_rec(); print('DASDMOD1_UNDO lastModulation is', repr(cfg.get(KEY)), '(stored by dasd since): receipt removed, file left as it is')
        else:
            orig=base64.b64decode(rec['file_before_b64']); old=plistlib.loads(orig); cfg[KEY]=old[KEY]
            out=plistlib.dumps(cfg,fmt=fmt,sort_keys=False)
            if sha(orig)==rec['sha_before'] and old==cfg: out=orig      # nothing else changed since: the file as it was, byte for byte
            put(PL,out,st.st_mode&0o7777,st.st_uid,st.st_gid); assert plistlib.loads(rd(PL))==cfg
            drop_rec(); print('DASDMOD1_UNDO lastModulation restored (%s) byte_identical_to_before=%s'%(rec['old_value'],sha(out)==rec['sha_before']))
os.sync()
